+
+func (w *gqlWalker) checkErrors(v any) {
+	list, ok := v.([]any)
+	if !ok {
+		w.addf("errors", "should be a list, but is %s", describeJSON(v))
+		return
+	}
+	for i, item := range list {
+		path := fmt.Sprintf("errors.%d", i)
